<?php
namespace Tests\Feature;
use App\Models\{AuditLog,DepositRequest,InvestmentAccount,Investor,SupportTicket,User};use App\Services\SupportTicketService;use DomainException;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class SupportTicketServiceTest extends TestCase{use RefreshDatabase;public function test_create_reply_internal_assignment_transitions_and_audit():void{[$investor,$user]=$this->context();$admin=User::factory()->create(['role'=>'admin','is_active'=>true]);$service=app(SupportTicketService::class);$ticket=$service->create($investor,$user,'finance','Вопрос','Первое сообщение','high');$this->assertCount(1,$ticket->messages);$this->assertDatabaseHas('audit_logs',['action'=>'support_ticket.created','entity_id'=>$ticket->id]);$service->changeStatus($ticket,$admin,'open');$service->changeStatus($ticket,$admin,'waiting_investor');$service->reply($ticket,$user,'Ответ инвестора');$this->assertSame('open',$ticket->fresh()->status);$note=$service->addInternalNote($ticket,$admin,'Скрытая заметка');$this->assertTrue($note->is_internal);$service->assign($ticket,$admin,$admin);$this->assertSame($admin->id,$ticket->fresh()->assigned_to_user_id);$service->resolve($ticket,$admin);$service->reply($ticket,$user,'Новый вопрос');$this->assertSame('open',$ticket->fresh()->status);$service->close($ticket,$admin);$this->expectException(DomainException::class);$service->reply($ticket,$user,'Нельзя');}
public function test_security_related_ownership_assignment_and_message_body():void{[$investor,$user,$account]=$this->context();[$other]=$this->context();$admin=User::factory()->create(['role'=>'admin','is_active'=>true]);$deposit=DepositRequest::create(['investor_id'=>$other->id,'investment_account_id'=>$other->investmentAccounts()->value('id'),'requested_amount'=>'1','currency'=>'USDT','status'=>'pending','requested_at'=>now()]);$service=app(SupportTicketService::class);foreach([fn()=>$service->create($investor,$user,'deposit','X','Y','normal','deposit_request',$deposit->id),fn()=>$service->create($investor,$user,'deposit','X','Y','normal','Anything\\Bad',1)] as $call){try{$call();$this->fail('Expected exception');}catch(DomainException){}}$ticket=$service->create($investor,$user,'general','Тема','Секретный текст сообщения');$payload=json_encode(AuditLog::where('action','support_ticket.created')->latest('id')->first()->toArray());$this->assertStringNotContainsString('Секретный текст',$payload);$this->expectException(DomainException::class);$service->assign($ticket,$admin,$user);}
public function test_invalid_transition_and_empty_create_leave_no_ticket():void{[$investor,$user]=$this->context();$admin=User::factory()->create(['role'=>'admin','is_active'=>true]);$s=app(SupportTicketService::class);try{$s->create($investor,$user,'general','Тема','','normal');}catch(DomainException){}$this->assertDatabaseCount('support_tickets',0);$t=$s->create($investor,$user,'general','Тема','Текст');$s->close($t,$admin);$this->expectException(DomainException::class);$s->changeStatus($t,$admin,'open');}
private function context():array{$u=User::factory()->create(['role'=>'investor','is_active'=>true]);$i=Investor::create(['user_id'=>$u->id,'code'=>'SUP-'.User::count(),'status'=>'active']);$a=InvestmentAccount::create(['investor_id'=>$i->id,'currency'=>'USDT','status'=>'active']);return[$i,$u,$a];}}
